#!/usr/bin/env python3
"""Plan 001 Step 3: Compute 15-model pairwise MI matrix and K_eff for all C(15,3) panels."""

import os
os.environ["HF_HOME"] = "/root/autodl-tmp/.hf_cache"

import sys
sys.path.insert(0, "/root/cert_manip_resist_eval")

import json
import itertools
import numpy as np
from pathlib import Path
from collections import Counter
from sklearn.metrics import mutual_info_score

from src.utils import setup_logging

logger = setup_logging("plan001_step3_mi")

# ── Model lists ──────────────────────────────────────────────────────
LOCAL_MODELS = [
    "qwen2.5-72b", "llama3.1-70b", "mistral-large",
    "qwen2.5-32b", "qwen2.5-14b", "llama3.1-8b",
]
API_MODELS = [
    "claude-opus-4", "gpt-5.5", "gemini-2.5-pro", "gpt-4.1",
    "claude-sonnet-4", "gpt-4o", "gemini-2.5-flash",
    "gpt-4o-mini", "claude-3-haiku",
]
ALL_MODELS = LOCAL_MODELS + API_MODELS
DATASETS = ["mmlu", "arc_challenge"]

# ── Paths ────────────────────────────────────────────────────────────
RESULTS_DIR = Path("/root/cert_manip_resist_eval/artifacts/results")
PLAN001_DIR = RESULTS_DIR / "plan001"
SCORES_DIR = PLAN001_DIR / "individual_scores"
MI_DIR = PLAN001_DIR / "mi_matrix"

STEP2V3_CKPT = RESULTS_DIR / "_step2v3_checkpoint.json"
TAXONOMY_CKPT = RESULTS_DIR / "_taxonomy_checkpoint.json"


def load_local_clean_scores():
    """Load clean scores for 6 local models from checkpoint files."""
    scores = {}
    for ckpt_path in [STEP2V3_CKPT, TAXONOMY_CKPT]:
        if not ckpt_path.exists():
            logger.warning(f"Checkpoint not found: {ckpt_path}")
            continue
        with open(ckpt_path) as f:
            data = json.load(f)
        cs = data.get("clean_scores", {})
        for ds in DATASETS:
            if ds not in cs:
                continue
            if ds not in scores:
                scores[ds] = {}
            for model_id, model_scores in cs[ds].items():
                if model_id in LOCAL_MODELS and model_id not in scores[ds]:
                    scores[ds][model_id] = model_scores
    return scores


def load_api_clean_scores():
    """Load clean scores for 9 API models from individual score files."""
    scores = {}
    for model_id in API_MODELS:
        for ds in DATASETS:
            fname = f"{model_id}__{ds}__clean.json"
            fpath = SCORES_DIR / fname
            if not fpath.exists():
                logger.warning(f"API score file not found: {fpath}")
                continue
            with open(fpath) as f:
                data = json.load(f)
            if ds not in scores:
                scores[ds] = {}
            scores[ds][model_id] = data.get("scores", [])
    return scores


def merge_clean_scores(local_scores, api_scores):
    """Merge local and API clean scores into unified dict."""
    merged = {}
    for ds in DATASETS:
        merged[ds] = {}
        for src in [local_scores, api_scores]:
            if ds in src:
                merged[ds].update(src[ds])
    return merged


def extract_winner_vector(score_list):
    """Extract winner labels from score list, normalizing to A/B/C/tie."""
    winners = []
    for s in score_list:
        w = s.get("winner", "tie") if isinstance(s, dict) else "tie"
        winners.append(w)
    return winners


def compute_pairwise_mi(winners_i, winners_j):
    """Compute mutual information between two winner vectors."""
    n = min(len(winners_i), len(winners_j))
    if n == 0:
        return 0.0
    return mutual_info_score(winners_i[:n], winners_j[:n])


def build_mi_matrix(clean_scores, dataset):
    """Build 15x15 MI matrix for a dataset."""
    ds_scores = clean_scores.get(dataset, {})
    n_models = len(ALL_MODELS)
    mi_mat = np.zeros((n_models, n_models))

    winner_vectors = {}
    for i, model_id in enumerate(ALL_MODELS):
        if model_id in ds_scores:
            winner_vectors[i] = extract_winner_vector(ds_scores[model_id])
        else:
            logger.warning(f"No clean scores for {model_id} on {dataset}")

    for i in range(n_models):
        for j in range(i + 1, n_models):
            if i in winner_vectors and j in winner_vectors:
                mi = compute_pairwise_mi(winner_vectors[i], winner_vectors[j])
                mi_mat[i, j] = mi
                mi_mat[j, i] = mi

    return mi_mat


def mi_based_keff(mi_matrix, model_indices):
    """K_eff = (1/K) * sum_i [1 + sum_{j!=i} exp(-2 * MI_ij)]"""
    K = len(model_indices)
    if K <= 1:
        return 1.0
    keff = 0.0
    for i_idx in model_indices:
        term = 1.0
        for j_idx in model_indices:
            if i_idx != j_idx:
                term += np.exp(-2 * mi_matrix[i_idx, j_idx])
        keff += term
    return keff / K


def compute_all_panel_keffs(mi_matrix, dataset):
    """Compute K_eff for all C(15,3)=455 panels."""
    n_models = len(ALL_MODELS)
    idx_to_model = {i: m for i, m in enumerate(ALL_MODELS)}
    panels = {}

    for combo in itertools.combinations(range(n_models), 3):
        model_ids = [idx_to_model[i] for i in combo]
        panel_key = "|".join(model_ids)
        keff = mi_based_keff(mi_matrix, list(combo))

        mi_pairs = {}
        for a, b in itertools.combinations(combo, 2):
            pair_key = f"{idx_to_model[a]}|{idx_to_model[b]}"
            mi_pairs[pair_key] = float(mi_matrix[a, b])

        panels[panel_key] = {
            "models": model_ids,
            "keff": float(keff),
            "mi_pairs": mi_pairs,
        }

    return panels


def main():
    logger.info("=== Plan 001 Step 3: MI Matrix Computation ===")

    local_scores = load_local_clean_scores()
    api_scores = load_api_clean_scores()
    clean_scores = merge_clean_scores(local_scores, api_scores)

    for ds in DATASETS:
        available = list(clean_scores.get(ds, {}).keys())
        missing = [m for m in ALL_MODELS if m not in available]
        logger.info(f"  {ds}: {len(available)}/{len(ALL_MODELS)} models available")
        if missing:
            logger.warning(f"  {ds}: missing models: {missing}")

    available_count = sum(
        1 for ds in DATASETS
        for m in ALL_MODELS
        if m in clean_scores.get(ds, {})
    )
    total_needed = len(DATASETS) * len(ALL_MODELS)
    if available_count < total_needed:
        logger.warning(
            f"Only {available_count}/{total_needed} model×dataset combos available. "
            f"MI matrix will have zeros for missing pairs."
        )

    mi_matrices = {}
    keff_per_panel = {}

    for ds in DATASETS:
        logger.info(f"\n--- Computing MI matrix for {ds} ---")
        mi_mat = build_mi_matrix(clean_scores, ds)
        mi_matrices[ds] = mi_mat.tolist()

        nonzero = np.count_nonzero(mi_mat)
        max_possible = len(ALL_MODELS) * (len(ALL_MODELS) - 1)
        logger.info(f"  MI matrix: {nonzero}/{max_possible} non-zero entries")
        if nonzero > 0:
            upper = mi_mat[np.triu_indices_from(mi_mat, k=1)]
            upper_nz = upper[upper > 0]
            if len(upper_nz) > 0:
                logger.info(
                    f"  MI range: [{upper_nz.min():.4f}, {upper_nz.max():.4f}], "
                    f"mean={upper_nz.mean():.4f}"
                )

        logger.info(f"  Computing K_eff for all C(15,3)=455 panels on {ds}...")
        panels = compute_all_panel_keffs(mi_mat, ds)
        keff_per_panel[ds] = panels

        keff_values = [p["keff"] for p in panels.values()]
        logger.info(
            f"  K_eff range: [{min(keff_values):.3f}, {max(keff_values):.3f}], "
            f"mean={np.mean(keff_values):.3f}"
        )

    MI_DIR.mkdir(parents=True, exist_ok=True)
    output = {
        "models": ALL_MODELS,
        "mi_matrix": mi_matrices,
        "keff_per_panel": keff_per_panel,
    }
    output_path = MI_DIR / "mi_matrix_15models.json"
    with open(output_path, "w") as f:
        json.dump(output, f, indent=2, ensure_ascii=False)
    logger.info(f"\nSaved MI matrix to {output_path}")

    print("\n" + "=" * 70)
    print("MI MATRIX SUMMARY")
    print("=" * 70)
    for ds in DATASETS:
        mi_mat = np.array(mi_matrices[ds])
        upper = mi_mat[np.triu_indices_from(mi_mat, k=1)]
        n_computed = np.count_nonzero(upper)
        print(f"\n{ds}:")
        print(f"  Pairwise MI computed: {n_computed}/105")
        if n_computed > 0:
            nz = upper[upper > 0]
            print(f"  MI range: [{nz.min():.4f}, {nz.max():.4f}]")
            print(f"  MI mean:  {nz.mean():.4f}")
        keffs = [p["keff"] for p in keff_per_panel[ds].values()]
        print(f"  K_eff (455 panels): [{min(keffs):.3f}, {max(keffs):.3f}], mean={np.mean(keffs):.3f}")
    print("=" * 70)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Plan 001: K_eff vs η_max confound diagnosis across all C(15,3) panels."""

import os
os.environ["HF_HOME"] = "/root/autodl-tmp/.hf_cache"

import sys
sys.path.insert(0, "/root/cert_manip_resist_eval")

import json
import itertools
import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from pathlib import Path
from scipy import stats

from src.utils import setup_logging

logger = setup_logging("plan001_confound")

# ── Model lists ──────────────────────────────────────────────────────
LOCAL_MODELS = [
    "qwen2.5-72b", "llama3.1-70b", "mistral-large",
    "qwen2.5-32b", "qwen2.5-14b", "llama3.1-8b",
]
API_MODELS = [
    "claude-opus-4", "gpt-5.5", "gemini-2.5-pro", "gpt-4.1",
    "claude-sonnet-4", "gpt-4o", "gemini-2.5-flash",
    "gpt-4o-mini", "claude-3-haiku",
]
ALL_MODELS = LOCAL_MODELS + API_MODELS
DATASETS = ["mmlu", "arc_challenge"]
ATTACKS = [
    "prompt_injection", "sycophancy", "score_manipulation",
    "verbosity_bias", "position_bias", "authority_bias",
]

# ── Paths ────────────────────────────────────────────────────────────
RESULTS_DIR = Path("/root/cert_manip_resist_eval/artifacts/results")
PLAN001_DIR = RESULTS_DIR / "plan001"
SCORES_DIR = PLAN001_DIR / "individual_scores"
MI_MATRIX_PATH = PLAN001_DIR / "mi_matrix" / "mi_matrix_15models.json"

STEP2V3_CKPT = RESULTS_DIR / "_step2v3_checkpoint.json"
TAXONOMY_CKPT = RESULTS_DIR / "_taxonomy_checkpoint.json"

# Attack → checkpoint mapping for local models
LOCAL_ATTACK_CKPT = {
    "prompt_injection": STEP2V3_CKPT,
    "sycophancy": STEP2V3_CKPT,
    "score_manipulation": STEP2V3_CKPT,
    "verbosity_bias": TAXONOMY_CKPT,
    "position_bias": TAXONOMY_CKPT,
    "authority_bias": TAXONOMY_CKPT,
}


def compute_asr_from_scores(clean_scores, attacked_scores, pairs):
    """Compute individual judge ASR: fraction of clean-correct flipped by attack."""
    n_flips = 0
    n_total = 0
    for clean, attacked, pair in zip(clean_scores, attacked_scores, pairs):
        gt = pair.get("ground_truth_winner")
        cw = clean.get("winner") if isinstance(clean, dict) else None
        aw = attacked.get("winner") if isinstance(attacked, dict) else None
        if cw == gt:
            n_total += 1
            if aw != gt:
                n_flips += 1
    return n_flips / max(n_total, 1)


def load_local_individual_asr():
    """Load per-model ASR for local models from checkpoint files.

    Returns: {dataset: {attack: {model_id: asr}}}
    """
    asr_data = {}
    ckpt_cache = {}

    for attack in ATTACKS:
        ckpt_path = LOCAL_ATTACK_CKPT[attack]
        if str(ckpt_path) not in ckpt_cache:
            if not ckpt_path.exists():
                logger.warning(f"Checkpoint not found: {ckpt_path}")
                continue
            with open(ckpt_path) as f:
                ckpt_cache[str(ckpt_path)] = json.load(f)
        data = ckpt_cache[str(ckpt_path)]

        for ds in DATASETS:
            if ds not in asr_data:
                asr_data[ds] = {}
            if attack not in asr_data[ds]:
                asr_data[ds][attack] = {}

            clean_all = data.get("clean_scores", {}).get(ds, {})
            atk_all = data.get("attacked_scores", {}).get(ds, {}).get(attack, {})
            pairs = data.get("pairs", {}).get(ds, [])

            if not pairs:
                logger.warning(f"No pairs for {ds} in {ckpt_path.name}")
                continue

            for model_id in LOCAL_MODELS:
                if model_id not in clean_all or model_id not in atk_all:
                    continue
                asr = compute_asr_from_scores(
                    clean_all[model_id], atk_all[model_id], pairs
                )
                asr_data[ds][attack][model_id] = asr

    return asr_data


def load_api_individual_asr():
    """Load per-model ASR for API models from individual score files.

    Returns: {dataset: {attack: {model_id: asr}}}
    """
    asr_data = {}
    for model_id in API_MODELS:
        for ds in DATASETS:
            if ds not in asr_data:
                asr_data[ds] = {}

            clean_path = SCORES_DIR / f"{model_id}__{ds}__clean.json"
            if not clean_path.exists():
                continue
            with open(clean_path) as f:
                clean_data = json.load(f)
            clean_scores = clean_data.get("scores", [])

            for attack in ATTACKS:
                if attack not in asr_data[ds]:
                    asr_data[ds][attack] = {}

                atk_path = SCORES_DIR / f"{model_id}__{ds}__{attack}.json"
                if not atk_path.exists():
                    continue
                with open(atk_path) as f:
                    atk_data = json.load(f)

                asr = atk_data.get("asr")
                if asr is not None:
                    asr_data[ds][attack][model_id] = asr
                else:
                    logger.warning(
                        f"No ASR in {atk_path.name}, skipping"
                    )

    return asr_data


def merge_asr(local_asr, api_asr):
    """Merge local and API ASR data."""
    merged = {}
    for ds in DATASETS:
        merged[ds] = {}
        for attack in ATTACKS:
            merged[ds][attack] = {}
            for src in [local_asr, api_asr]:
                if ds in src and attack in src[ds]:
                    merged[ds][attack].update(src[ds][attack])
    return merged


def load_mi_matrix():
    """Load MI matrix from Step 3 output."""
    if not MI_MATRIX_PATH.exists():
        logger.error(f"MI matrix not found: {MI_MATRIX_PATH}")
        sys.exit(1)
    with open(MI_MATRIX_PATH) as f:
        data = json.load(f)
    return data


def mi_based_keff(mi_matrix_np, model_indices):
    """K_eff = (1/K) * sum_i [1 + sum_{j!=i} exp(-2 * MI_ij)]"""
    K = len(model_indices)
    if K <= 1:
        return 1.0
    keff = 0.0
    for i_idx in model_indices:
        term = 1.0
        for j_idx in model_indices:
            if i_idx != j_idx:
                term += np.exp(-2 * mi_matrix_np[i_idx, j_idx])
        keff += term
    return keff / K


def classify_panel(model_ids):
    """Classify panel by composition for scatter plot coloring."""
    n_api = sum(1 for m in model_ids if m in API_MODELS)
    if n_api == 3:
        return "all_api"
    elif n_api == 0:
        return "all_local"
    elif n_api == 2:
        return "2api_1local"
    else:
        return "1api_2local"


PANEL_COLORS = {
    "all_api": "#e74c3c",
    "all_local": "#2ecc71",
    "2api_1local": "#e67e22",
    "1api_2local": "#3498db",
}

PANEL_LABELS = {
    "all_api": "3 API",
    "all_local": "3 Local",
    "2api_1local": "2 API + 1 Local",
    "1api_2local": "1 API + 2 Local",
}


def run_confound_analysis(mi_data, asr_data):
    """Run K_eff vs η_max analysis for all conditions."""
    models = mi_data["models"]
    model_to_idx = {m: i for i, m in enumerate(models)}
    conditions = {}

    for ds in DATASETS:
        mi_mat = np.array(mi_data["mi_matrix"][ds])

        for attack in ATTACKS:
            cond_key = f"{ds}×{attack}"
            model_asrs = asr_data.get(ds, {}).get(attack, {})

            if len(model_asrs) < 3:
                logger.warning(
                    f"  {cond_key}: only {len(model_asrs)} models have ASR, "
                    f"need ≥3 for panel construction. Skipping."
                )
                conditions[cond_key] = {
                    "pearson_r": None,
                    "p_value": None,
                    "verdict": "INSUFFICIENT_DATA",
                    "n_panels": 0,
                    "n_models_with_asr": len(model_asrs),
                }
                continue

            available_models = [
                m for m in models if m in model_asrs
            ]

            keffs = []
            eta_maxs = []
            panel_types = []

            for combo in itertools.combinations(available_models, 3):
                indices = [model_to_idx[m] for m in combo]
                keff = mi_based_keff(mi_mat, indices)
                eta_max = max(model_asrs[m] for m in combo)

                keffs.append(keff)
                eta_maxs.append(eta_max)
                panel_types.append(classify_panel(combo))

            keffs = np.array(keffs)
            eta_maxs = np.array(eta_maxs)

            if len(keffs) < 3 or np.std(keffs) < 1e-10 or np.std(eta_maxs) < 1e-10:
                r, p = 0.0, 1.0
            else:
                r, p = stats.pearsonr(keffs, eta_maxs)

            if r < -0.7:
                verdict = "CONFOUND_SEVERE"
            elif r <= -0.5:
                verdict = "CONFOUND_MODERATE"
            else:
                verdict = "CONFOUND_BROKEN"

            conditions[cond_key] = {
                "pearson_r": float(r),
                "p_value": float(p),
                "verdict": verdict,
                "n_panels": len(keffs),
                "n_models_with_asr": len(available_models),
                "keffs": keffs.tolist(),
                "eta_maxs": eta_maxs.tolist(),
                "panel_types": panel_types,
            }
            logger.info(
                f"  {cond_key}: r={r:.3f}, p={p:.4f}, "
                f"verdict={verdict}, n_panels={len(keffs)}"
            )

    return conditions


def plot_scatter_grid(conditions, output_path):
    """Plot K_eff vs η_max scatter grid."""
    valid_conds = {
        k: v for k, v in conditions.items()
        if v.get("pearson_r") is not None
    }
    n = len(valid_conds)
    if n == 0:
        logger.warning("No valid conditions to plot")
        return

    if n <= 6:
        nrows, ncols = 2, 3
    elif n <= 9:
        nrows, ncols = 3, 3
    else:
        nrows, ncols = 3, 4

    fig, axes = plt.subplots(
        nrows, ncols,
        figsize=(5 * ncols, 4 * nrows),
        squeeze=False,
    )

    for idx, (cond_key, cond_data) in enumerate(sorted(valid_conds.items())):
        row, col = divmod(idx, ncols)
        ax = axes[row][col]

        keffs = np.array(cond_data["keffs"])
        eta_maxs = np.array(cond_data["eta_maxs"])
        panel_types = cond_data["panel_types"]
        r = cond_data["pearson_r"]
        verdict = cond_data["verdict"]

        plotted_labels = set()
        for pt in ["all_local", "1api_2local", "2api_1local", "all_api"]:
            mask = [t == pt for t in panel_types]
            if not any(mask):
                continue
            k_sub = keffs[mask]
            e_sub = eta_maxs[mask]
            label = PANEL_LABELS[pt] if pt not in plotted_labels else None
            ax.scatter(
                k_sub, e_sub,
                c=PANEL_COLORS[pt],
                alpha=0.4, s=12, label=label,
                edgecolors="none",
            )
            plotted_labels.add(pt)

        verdict_color = {
            "CONFOUND_SEVERE": "#e74c3c",
            "CONFOUND_MODERATE": "#e67e22",
            "CONFOUND_BROKEN": "#27ae60",
        }.get(verdict, "#333")

        ax.set_title(
            f"{cond_key}\nr = {r:.3f}  [{verdict}]",
            fontsize=9,
            color=verdict_color,
        )
        ax.set_xlabel("K_eff", fontsize=8)
        ax.set_ylabel("η_max (individual ASR)", fontsize=8)
        ax.tick_params(labelsize=7)

        if len(keffs) >= 3 and np.std(keffs) > 1e-10:
            z = np.polyfit(keffs, eta_maxs, 1)
            x_line = np.linspace(keffs.min(), keffs.max(), 50)
            ax.plot(x_line, np.polyval(z, x_line), "k--", alpha=0.3, linewidth=1)

        if idx == 0:
            ax.legend(fontsize=6, loc="best", framealpha=0.7)

    for idx in range(len(valid_conds), nrows * ncols):
        row, col = divmod(idx, ncols)
        axes[row][col].set_visible(False)

    fig.suptitle(
        "K_eff vs η_max Confound Diagnosis (15 models, K=3 panels)",
        fontsize=12, y=1.02,
    )
    plt.tight_layout()
    plt.savefig(output_path, dpi=150, bbox_inches="tight")
    plt.close()
    logger.info(f"Scatter plot saved to {output_path}")


def main():
    logger.info("=== Plan 001: K_eff vs η_max Confound Diagnosis ===")

    logger.info("Loading MI matrix...")
    mi_data = load_mi_matrix()

    logger.info("Loading individual ASR data...")
    local_asr = load_local_individual_asr()
    api_asr = load_api_individual_asr()
    asr_data = merge_asr(local_asr, api_asr)

    for ds in DATASETS:
        for attack in ATTACKS:
            models_with_asr = list(asr_data.get(ds, {}).get(attack, {}).keys())
            logger.info(f"  {ds}×{attack}: {len(models_with_asr)} models")

    logger.info("\nRunning confound analysis...")
    conditions = run_confound_analysis(mi_data, asr_data)

    scatter_path = PLAN001_DIR / "confound_scatter.png"
    plot_scatter_grid(conditions, scatter_path)

    r_values = [
        v["pearson_r"] for v in conditions.values()
        if v.get("pearson_r") is not None
    ]
    if r_values:
        mean_r = float(np.mean(r_values))
        if mean_r < -0.7:
            overall = "CONFOUND_SEVERE"
        elif mean_r <= -0.5:
            overall = "CONFOUND_MODERATE"
        else:
            overall = "CONFOUND_BROKEN"
    else:
        mean_r = None
        overall = "INSUFFICIENT_DATA"

    output_conditions = {}
    for k, v in conditions.items():
        output_conditions[k] = {
            "pearson_r": v.get("pearson_r"),
            "p_value": v.get("p_value"),
            "verdict": v.get("verdict"),
            "n_panels": v.get("n_panels"),
